import{_ as e,o as a,c as d,a2 as l}from"./chunks/framework.CAlA1Nx7.js";const h=JSON.parse('{"title":"Vito API Reference 📚","description":"","frontmatter":{},"headers":[],"relativePath":"en/api/overview.md","filePath":"en/api/overview.md"}'),o={name:"en/api/overview.md"};function i(s,t,r,c,n,g){return a(),d("div",null,[...t[0]||(t[0]=[l('<h1 id="vito-api-reference-📚" tabindex="-1">Vito API Reference 📚 <a class="header-anchor" href="#vito-api-reference-📚" aria-label="Permalink to &quot;Vito API Reference 📚&quot;">​</a></h1><p>Detailed documentation for the core functions and objects of the <strong>Vito Web Framework Core Engine</strong>.</p><hr><h2 id="🏗-vitoapp-class" tabindex="-1">🏗 <code>VitoApp</code> Class <a class="header-anchor" href="#🏗-vitoapp-class" aria-label="Permalink to &quot;🏗 `VitoApp` Class&quot;">​</a></h2><h3 id="createapp" tabindex="-1"><code>createApp()</code> <a class="header-anchor" href="#createapp" aria-label="Permalink to &quot;`createApp()`&quot;">​</a></h3><p>Initialize a new Vito application instance.</p><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">let</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> app </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> createApp</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span></code></pre></div><h3 id="app-get-path-handler-app-post-path-handler-app-put-app-delete" tabindex="-1"><code>app.get(path, handler)</code> / <code>app.post(path, handler)</code> / <code>app.put()</code> / <code>app.delete()</code> <a class="header-anchor" href="#app-get-path-handler-app-post-path-handler-app-put-app-delete" aria-label="Permalink to &quot;`app.get(path, handler)` / `app.post(path, handler)` / `app.put()` / `app.delete()`&quot;">​</a></h3><p>Register a route handler for the corresponding HTTP method.</p><h3 id="app-group-prefix-callback" tabindex="-1"><code>app.group(prefix, callback)</code> <a class="header-anchor" href="#app-group-prefix-callback" aria-label="Permalink to &quot;`app.group(prefix, callback)`&quot;">​</a></h3><p>Create a group of paths sharing a common URL prefix.</p><h3 id="app-use-middleware" tabindex="-1"><code>app.use(middleware)</code> <a class="header-anchor" href="#app-use-middleware" aria-label="Permalink to &quot;`app.use(middleware)`&quot;">​</a></h3><p>Add middleware to the request processing pipeline.</p><h3 id="app-setstrictslash-strict-boolean" tabindex="-1"><code>app.setStrictSlash(strict: boolean)</code> <a class="header-anchor" href="#app-setstrictslash-strict-boolean" aria-label="Permalink to &quot;`app.setStrictSlash(strict: boolean)`&quot;">​</a></h3><p>Enable/disable Strict Trailing Slash Normalization (<code>/users/</code> vs <code>/users</code>). Default: <code>false</code> (Lax mode).</p><h3 id="app-setnotfoundhandler-handler" tabindex="-1"><code>app.setNotFoundHandler(handler)</code> <a class="header-anchor" href="#app-setnotfoundhandler-handler" aria-label="Permalink to &quot;`app.setNotFoundHandler(handler)`&quot;">​</a></h3><p>Set a custom handler when no route is found (404 Not Found).</p><h3 id="app-listen-port" tabindex="-1"><code>app.listen(port)</code> <a class="header-anchor" href="#app-listen-port" aria-label="Permalink to &quot;`app.listen(port)`&quot;">​</a></h3><p>Open the socket and begin listening for HTTP connections on the specified port.</p><hr><h2 id="📊-observability-metrics-dx-phase-14" tabindex="-1">📊 Observability, Metrics &amp; DX (<code>Phase 14</code>) <a class="header-anchor" href="#📊-observability-metrics-dx-phase-14" aria-label="Permalink to &quot;📊 Observability, Metrics &amp; DX (`Phase 14`)&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Function / Structure</th><th style="text-align:left;">Package</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><code>createPrometheusRegistry()</code></td><td style="text-align:left;"><code>packages/metrics/metrics.vit</code></td><td style="text-align:left;">Initialize a Prometheus Metrics Registry collecting HTTP &amp; OS metrics.</td></tr><tr><td style="text-align:left;"><code>registry.recordRequest(method, path, status, duration)</code></td><td style="text-align:left;"><code>packages/metrics/metrics.vit</code></td><td style="text-align:left;">Record HTTP Request metrics for latency percentiles (p50, p90, p99).</td></tr><tr><td style="text-align:left;"><code>registry.renderPrometheusMetrics()</code></td><td style="text-align:left;"><code>packages/metrics/metrics.vit</code></td><td style="text-align:left;">Export data in standard Prometheus exposition text format.</td></tr><tr><td style="text-align:left;"><code>extractTraceParent(header)</code> / <code>injectTraceParent</code></td><td style="text-align:left;"><code>packages/metrics/metrics.vit</code></td><td style="text-align:left;">Extract and propagate OpenTelemetry (OTel) W3C <code>traceparent</code> headers.</td></tr><tr><td style="text-align:left;"><code>createMockHttpEngine()</code></td><td style="text-align:left;"><code>packages/testing/testing.vit</code></td><td style="text-align:left;">Initialize an In-Memory Fast HTTP Injector for Test Suites.</td></tr><tr><td style="text-align:left;"><code>mockEngine.inject(app, method, path, headers, body)</code></td><td style="text-align:left;"><code>packages/testing/testing.vit</code></td><td style="text-align:left;">Simulate HTTP Requests directly in RAM without TCP socket.</td></tr><tr><td style="text-align:left;"><code>createTestDbFixture(name)</code></td><td style="text-align:left;"><code>packages/testing/testing.vit</code></td><td style="text-align:left;">Initialize a sample data loader for Test Suites.</td></tr><tr><td style="text-align:left;"><code>fixture.beginIsolationTransaction()</code> / <code>rollbackIsolationTransaction</code></td><td style="text-align:left;"><code>packages/testing/testing.vit</code></td><td style="text-align:left;">Automatically ROLLBACK the DB after each test case to maintain clean state.</td></tr><tr><td style="text-align:left;"><code>createVitCodeGenerator()</code></td><td style="text-align:left;"><code>packages/cli/cli.vit</code></td><td style="text-align:left;">Generate template source code for Controller, Service, Middleware, Model, Migration.</td></tr><tr><td style="text-align:left;"><code>createVitDoctor()</code></td><td style="text-align:left;"><code>packages/cli/cli.vit</code></td><td style="text-align:left;">Execute development environment diagnostics and system resource checks.</td></tr></tbody></table><hr><h2 id="🔒-auth-security-suite-packages-packages-auth" tabindex="-1">🔒 Auth &amp; Security Suite Packages (<code>packages/auth/</code>) <a class="header-anchor" href="#🔒-auth-security-suite-packages-packages-auth" aria-label="Permalink to &quot;🔒 Auth &amp; Security Suite Packages (`packages/auth/`)&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Function / Struct</th><th style="text-align:left;">Package</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><code>verifyJwtToken(token, secret, algo)</code></td><td style="text-align:left;"><code>packages/auth/jwt.vit</code></td><td style="text-align:left;">Verify JWT Token signature (<code>HS256</code>, <code>RS256</code>, <code>ES256</code>) in &lt; 0.1ms.</td></tr><tr><td style="text-align:left;"><code>parseJwtToken(token)</code></td><td style="text-align:left;"><code>packages/auth/jwt.vit</code></td><td style="text-align:left;">Extract Header and Payload Claims from a raw JWT string.</td></tr><tr><td style="text-align:left;"><code>validateJwtClaims(jwt, now, exp, nbf)</code></td><td style="text-align:left;"><code>packages/auth/jwt.vit</code></td><td style="text-align:left;">Validate expiry (<code>exp</code>) and not-before (<code>nbf</code>) timestamps.</td></tr><tr><td style="text-align:left;"><code>jwtGuardMiddleware</code></td><td style="text-align:left;"><code>packages/auth/jwt.vit</code></td><td style="text-align:left;">Middleware that auto-validates Bearer tokens and rejects HTTP 401 on failure.</td></tr><tr><td style="text-align:left;"><code>createGoogleOAuthProvider(...)</code></td><td style="text-align:left;"><code>packages/auth/oauth.vit</code></td><td style="text-align:left;">Initialize OAuth2 &amp; OIDC Config for Google Provider with PKCE.</td></tr><tr><td style="text-align:left;"><code>createGitHubOAuthProvider(...)</code></td><td style="text-align:left;"><code>packages/auth/oauth.vit</code></td><td style="text-align:left;">Initialize OAuth2 Config for GitHub Provider.</td></tr><tr><td style="text-align:left;"><code>createMicrosoftOAuthProvider(...)</code></td><td style="text-align:left;"><code>packages/auth/oauth.vit</code></td><td style="text-align:left;">Initialize OAuth2 Config for Microsoft Azure AD / Entra ID.</td></tr><tr><td style="text-align:left;"><code>config.generateAuthorizationUrl(state, challenge)</code></td><td style="text-align:left;"><code>packages/auth/oauth.vit</code></td><td style="text-align:left;">Generate OAuth2 redirect login URL with PKCE challenge.</td></tr><tr><td style="text-align:left;"><code>createApiKeyStore()</code></td><td style="text-align:left;"><code>packages/auth/apikey.vit</code></td><td style="text-align:left;">Initialize API Key storage and per-client-key Rate Limit management.</td></tr><tr><td style="text-align:left;"><code>hashApiKey(rawKey)</code></td><td style="text-align:left;"><code>packages/auth/apikey.vit</code></td><td style="text-align:left;">One-way hash an API Key securely for database storage.</td></tr><tr><td style="text-align:left;"><code>hashPasswordArgon2id(pass, salt, params)</code></td><td style="text-align:left;"><code>packages/auth/crypto.vit</code></td><td style="text-align:left;">Hash passwords with Argon2id following OWASP recommendations.</td></tr><tr><td style="text-align:left;"><code>hashPasswordBcrypt(pass, salt, cost)</code></td><td style="text-align:left;"><code>packages/auth/crypto.vit</code></td><td style="text-align:left;">Hash passwords with Bcrypt using a custom Cost Factor.</td></tr><tr><td style="text-align:left;"><code>encryptAES256GCM(plain, key, iv, ad)</code></td><td style="text-align:left;"><code>packages/auth/crypto.vit</code></td><td style="text-align:left;">Two-way encrypt data using AES-256-GCM AEAD (<code>iv:ciphertext:tag</code>).</td></tr><tr><td style="text-align:left;"><code>decryptAES256GCM(payload, key, ad)</code></td><td style="text-align:left;"><code>packages/auth/crypto.vit</code></td><td style="text-align:left;">Decrypt data and verify GCM Tag integrity.</td></tr><tr><td style="text-align:left;"><code>timingSafeEqual(strA, strB)</code></td><td style="text-align:left;"><code>packages/auth/crypto.vit</code></td><td style="text-align:left;">Constant-time string comparison to prevent Side-channel Timing Attacks.</td></tr><tr><td style="text-align:left;"><code>createRoleGuard(role, currentRoles)</code></td><td style="text-align:left;"><code>packages/auth/rbac.vit</code></td><td style="text-align:left;">Initialize RBAC Guard to check user roles (rejects HTTP 403).</td></tr><tr><td style="text-align:left;"><code>createPermissionGuard(perm, currentPerms)</code></td><td style="text-align:left;"><code>packages/auth/rbac.vit</code></td><td style="text-align:left;">Initialize RBAC Guard to check route operation permissions.</td></tr><tr><td style="text-align:left;"><code>createGateEngine()</code></td><td style="text-align:left;"><code>packages/auth/rbac.vit</code></td><td style="text-align:left;">Initialize ABAC Engine for context-based resource authorization.</td></tr></tbody></table><hr><h2 id="🗄️-database-orm-packages-packages-db-packages-orm" tabindex="-1">🗄️ Database &amp; ORM Packages (<code>packages/db</code> &amp; <code>packages/orm</code>) <a class="header-anchor" href="#🗄️-database-orm-packages-packages-db-packages-orm" aria-label="Permalink to &quot;🗄️ Database &amp; ORM Packages (`packages/db` &amp; `packages/orm`)&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Function / Struct</th><th style="text-align:left;">Package</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><code>createConnectionPool(type, connStr, min, max)</code></td><td style="text-align:left;"><code>packages/db/db_pool.vit</code></td><td style="text-align:left;">Initialize a Connection Pool with automatic scaling and silent reconnection.</td></tr><tr><td style="text-align:left;"><code>pool.acquireConnection()</code></td><td style="text-align:left;"><code>packages/db/db_pool.vit</code></td><td style="text-align:left;">Borrow a valid database connection from the Pool.</td></tr><tr><td style="text-align:left;"><code>pool.checkHealthAndReconnect()</code></td><td style="text-align:left;"><code>packages/db/db_pool.vit</code></td><td style="text-align:left;">Check connection health &amp; auto-reconnect silently (&lt; 100ms).</td></tr><tr><td style="text-align:left;"><code>beginTransaction(id)</code></td><td style="text-align:left;"><code>packages/orm/transaction.vit</code></td><td style="text-align:left;">Initialize an Atomic Database Transaction supporting ACID.</td></tr><tr><td style="text-align:left;"><code>tx.createSavepoint(name)</code></td><td style="text-align:left;"><code>packages/orm/transaction.vit</code></td><td style="text-align:left;">Create a Savepoint for nested transactions.</td></tr><tr><td style="text-align:left;"><code>tx.rollbackToSavepoint(name)</code></td><td style="text-align:left;"><code>packages/orm/transaction.vit</code></td><td style="text-align:left;">Roll back transaction state to the specified Savepoint.</td></tr><tr><td style="text-align:left;"><code>createMigrationRunner()</code></td><td style="text-align:left;"><code>packages/orm/migration.vit</code></td><td style="text-align:left;">Create an object for managing and running Migrations (Up/Down) stored in <code>schema_migrations</code>.</td></tr><tr><td style="text-align:left;"><code>createSchemaDiffGenerator()</code></td><td style="text-align:left;"><code>packages/orm/migration.vit</code></td><td style="text-align:left;">Auto-generate SQL Migration statements from Vito ORM Model definitions.</td></tr><tr><td style="text-align:left;"><code>createDatabaseSeeder()</code></td><td style="text-align:left;"><code>packages/orm/migration.vit</code></td><td style="text-align:left;">Create a sample data seeder for Dev &amp; Staging environments.</td></tr></tbody></table><hr><h2 id="⚡-performance-packages-packages-pool-packages-router" tabindex="-1">⚡ Performance Packages (<code>packages/pool</code> &amp; <code>packages/router</code>) <a class="header-anchor" href="#⚡-performance-packages-packages-pool-packages-router" aria-label="Permalink to &quot;⚡ Performance Packages (`packages/pool` &amp; `packages/router`)&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Function / Helper</th><th style="text-align:left;">Package</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><code>createMemoryArena()</code></td><td style="text-align:left;"><code>packages/pool/pool.vit</code></td><td style="text-align:left;">Create a reusable Request Memory Arena slot manager.</td></tr><tr><td style="text-align:left;"><code>createTcpBufferPool()</code></td><td style="text-align:left;"><code>packages/pool/pool.vit</code></td><td style="text-align:left;">Create a Buffer Recycling Pool for TCP Read/Write buffers.</td></tr><tr><td style="text-align:left;"><code>zeroAllocHeaderLookup(raw, target)</code></td><td style="text-align:left;"><code>packages/pool/pool.vit</code></td><td style="text-align:left;">Extract Header values directly from raw HTTP stream without memory allocation.</td></tr><tr><td style="text-align:left;"><code>createRadixRouter(strict)</code></td><td style="text-align:left;"><code>packages/router/router.vit</code></td><td style="text-align:left;">Initialize a Radix Trie Router with O(1) Static Route Fast Path.</td></tr><tr><td style="text-align:left;"><code>normalizePath(path, strict)</code></td><td style="text-align:left;"><code>packages/router/router.vit</code></td><td style="text-align:left;">Normalize URL paths in Lax / Strict slash mode.</td></tr></tbody></table><hr><h2 id="📥-request-class" tabindex="-1">📥 <code>Request</code> Class <a class="header-anchor" href="#📥-request-class" aria-label="Permalink to &quot;📥 `Request` Class&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Method</th><th style="text-align:left;">Description</th><th style="text-align:left;">Example</th></tr></thead><tbody><tr><td style="text-align:left;"><code>req.param(key)</code></td><td style="text-align:left;">Get value of dynamic path parameter <code>:key</code> or <code>*wildcard</code></td><td style="text-align:left;"><code>req.param(&quot;id&quot;)</code></td></tr><tr><td style="text-align:left;"><code>req.query(key)</code></td><td style="text-align:left;">Get value of search query string <code>?key=val</code></td><td style="text-align:left;"><code>req.query(&quot;page&quot;)</code></td></tr><tr><td style="text-align:left;"><code>req.header(key)</code></td><td style="text-align:left;">Get HTTP request header value</td><td style="text-align:left;"><code>req.header(&quot;Authorization&quot;)</code></td></tr><tr><td style="text-align:left;"><code>req.method</code></td><td style="text-align:left;">Property returning the HTTP method (GET, POST...)</td><td style="text-align:left;"><code>req.method</code></td></tr><tr><td style="text-align:left;"><code>req.path</code></td><td style="text-align:left;">Property returning the URL path</td><td style="text-align:left;"><code>req.path</code></td></tr></tbody></table><hr><h2 id="📤-response-class" tabindex="-1">📤 <code>Response</code> Class <a class="header-anchor" href="#📤-response-class" aria-label="Permalink to &quot;📤 `Response` Class&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Method</th><th style="text-align:left;">Description</th><th style="text-align:left;">Example</th></tr></thead><tbody><tr><td style="text-align:left;"><code>res.setStatus(code)</code></td><td style="text-align:left;">Set HTTP Status Code (200, 404, 500...)</td><td style="text-align:left;"><code>res.setStatus(200)</code></td></tr><tr><td style="text-align:left;"><code>res.setHeader(name, val)</code></td><td style="text-align:left;">Set HTTP Response Header</td><td style="text-align:left;"><code>res.setHeader(&quot;X-Powered-By&quot;, &quot;Vito&quot;)</code></td></tr><tr><td style="text-align:left;"><code>res.setCookie(key, val, opts)</code></td><td style="text-align:left;">Write Cookie with HMAC signature &amp; HttpOnly/SameSite flags</td><td style="text-align:left;"><code>res.setCookie(&quot;sid&quot;, &quot;abc&quot;, opts)</code></td></tr><tr><td style="text-align:left;"><code>res.json(jsonStr)</code></td><td style="text-align:left;">Return JSON string with <code>Content-Type: application/json</code> header</td><td style="text-align:left;"><code>res.json(&quot;{\\&quot;ok\\&quot;:true}&quot;)</code></td></tr><tr><td style="text-align:left;"><code>res.html(htmlStr)</code></td><td style="text-align:left;">Return HTML content with <code>Content-Type: text/html</code></td><td style="text-align:left;"><code>res.html(&quot;&lt;h1&gt;Hi&lt;/h1&gt;&quot;)</code></td></tr><tr><td style="text-align:left;"><code>res.send(textStr)</code></td><td style="text-align:left;">Return plain text string</td><td style="text-align:left;"><code>res.send(&quot;Hello World&quot;)</code></td></tr><tr><td style="text-align:left;"><code>res.sendChunk(chunk)</code></td><td style="text-align:left;">Return data as Stream / Chunked response</td><td style="text-align:left;"><code>res.sendChunk(data)</code></td></tr></tbody></table><hr><h2 id="⚡-websockets-event-bus-job-queue-phase-13" tabindex="-1">⚡ WebSockets, Event Bus &amp; Job Queue (<code>Phase 13</code>) <a class="header-anchor" href="#⚡-websockets-event-bus-job-queue-phase-13" aria-label="Permalink to &quot;⚡ WebSockets, Event Bus &amp; Job Queue (`Phase 13`)&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Function / Structure</th><th style="text-align:left;">Package</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><code>createWebSocketServer(port, maxConn)</code></td><td style="text-align:left;"><code>packages/websocket/websocket.vit</code></td><td style="text-align:left;">Initialize a High-Concurrency WebSocket Server engine.</td></tr><tr><td style="text-align:left;"><code>wsServer.broadcastToRoom(room, msg)</code></td><td style="text-align:left;"><code>packages/websocket/websocket.vit</code></td><td style="text-align:left;">Broadcast a message to all connections in a Room.</td></tr><tr><td style="text-align:left;"><code>wsServer.unicast(client, msg)</code></td><td style="text-align:left;"><code>packages/websocket/websocket.vit</code></td><td style="text-align:left;">Send a message to a specific WebSocket Client.</td></tr><tr><td style="text-align:left;"><code>wsServer.checkHeartbeats(client, time)</code></td><td style="text-align:left;"><code>packages/websocket/websocket.vit</code></td><td style="text-align:left;">Check Ping/Pong and evict stale connections.</td></tr><tr><td style="text-align:left;"><code>compressFrame(payload)</code> / <code>decompressFrame</code></td><td style="text-align:left;"><code>packages/websocket/websocket.vit</code></td><td style="text-align:left;">Compress and decompress WebSocket frame data with per-message deflate.</td></tr><tr><td style="text-align:left;"><code>createEventBus()</code></td><td style="text-align:left;"><code>packages/events/event_bus.vit</code></td><td style="text-align:left;">Initialize an Async Internal Event Bus dispatcher.</td></tr><tr><td style="text-align:left;"><code>eventBus.emitAsync(event, payload)</code></td><td style="text-align:left;"><code>packages/events/event_bus.vit</code></td><td style="text-align:left;">Emit an asynchronous event without blocking the main thread.</td></tr><tr><td style="text-align:left;"><code>createRedisPubSubAdapter(host, port)</code></td><td style="text-align:left;"><code>packages/events/redis_pubsub.vit</code></td><td style="text-align:left;">Create a Redis Pub/Sub adapter for inter-node communication in a Server cluster.</td></tr><tr><td style="text-align:left;"><code>createJobQueue(driver)</code></td><td style="text-align:left;"><code>packages/queue/queue.vit</code></td><td style="text-align:left;">Initialize Background Job Queue (Driver: <code>&quot;memory&quot;</code> or <code>&quot;redis&quot;</code>).</td></tr><tr><td style="text-align:left;"><code>jobQueue.scheduleJob(job, delayMs)</code></td><td style="text-align:left;"><code>packages/queue/queue.vit</code></td><td style="text-align:left;">Push a job to the delayed queue with a configured delay.</td></tr><tr><td style="text-align:left;"><code>jobQueue.processNextJob(shouldFail, reason)</code></td><td style="text-align:left;"><code>packages/queue/queue.vit</code></td><td style="text-align:left;">Process the next job, supporting Exponential Backoff Retry &amp; DLQ.</td></tr></tbody></table>',40)])])}const f=e(o,[["render",i]]);export{h as __pageData,f as default};
